module protocol::interest;

use math::float::{Self, Decimal};

public struct InterestModel has copy, drop, store {
    base_borrow_rate_per_sec: Decimal,
    borrow_rate_on_mid_kink: Decimal,
    mid_kink: Decimal,
    borrow_rate_on_high_kink: Decimal,
    high_kink: Decimal,
    max_borrow_rate: Decimal,
}

public(package) fun base_borrow_rate(model: &InterestModel): Decimal { model.base_borrow_rate_per_sec }
public(package) fun borrow_rate_on_mid_kink(model: &InterestModel): Decimal { model.borrow_rate_on_mid_kink}
public(package) fun mid_kink(model: &InterestModel): Decimal { model.mid_kink }
public(package) fun borrow_rate_on_high_kink(model: &InterestModel): Decimal { model.borrow_rate_on_high_kink }
public(package) fun high_kink(model: &InterestModel): Decimal { model.high_kink }
public(package) fun max_borrow_rate(model: &InterestModel): Decimal { model.max_borrow_rate }

/// Create a new interest model
public(package) fun new(
    base_borrow_rate_per_sec: Decimal,
    borrow_rate_on_mid_kink: Decimal,
    mid_kink: Decimal,
    borrow_rate_on_high_kink: Decimal,
    high_kink: Decimal,
    max_borrow_rate: Decimal,
): InterestModel {
    InterestModel {
        base_borrow_rate_per_sec,
        borrow_rate_on_mid_kink,
        mid_kink,
        borrow_rate_on_high_kink,
        high_kink,
        max_borrow_rate,
    }
}

// Return the interest rate under the given utilization rate
// Notice: the interest rate is scaled by a factor, because it's too small to be used directly
public(package) fun calc_interest(
    interest_model: &InterestModel,
    util_rate: Decimal,
): Decimal {
    let borrow_rate_on_mid_kink = interest_model.borrow_rate_on_mid_kink;
    let mid_kink = interest_model.mid_kink;
    let borrow_rate_on_high_kink = interest_model.borrow_rate_on_high_kink;
    let high_kink = interest_model.high_kink;
    let max_borrow_rate = interest_model.max_borrow_rate;
    let base_rate = interest_model.base_borrow_rate_per_sec;
    /* ================== Interest Rate Formula ==================

    Calculate the interest rate with the given utlilization rate of the pool
    if util_rate <= mid_kink:
      interest_rate = (util_rate / mid_kink) * (borrow_rate_on_mid_kink - base_rate) + base_rate
    else if util_rate <= high_kink:
      interest_rate = ((util_rate - mid_kink) / (high_kink - mid_kink)) * (borrow_rate_on_high_kink - borrow_rate_on_mid_kink) + borrow_rate_on_mid_kink
    else:
      interest_rate = ((util_rate - high_kink) / (1 - high_kink)) * (max_borrow_rate - borrow_rate_on_high_kink) + borrow_rate_on_high_kink

    ============================================================== */

    let borrow_rate = if (float::ge(mid_kink, util_rate)) {
        let weight = float::div(util_rate, mid_kink);
        let range = float::sub(borrow_rate_on_mid_kink, base_rate);

        float::add(
            // `weight` is like how far it goes from the starting point within the `range`
            float::mul(weight, range),
            // base borrow rate is the starting point
            base_rate,
        )
    } else if (float::ge(high_kink, util_rate)) {
        let weight = float::div(
            float::sub(util_rate, mid_kink),
            float::sub(high_kink, mid_kink),
        );
        let range = float::sub(borrow_rate_on_high_kink, borrow_rate_on_mid_kink);

        float::add(
            float::mul(weight, range),
            borrow_rate_on_mid_kink,
        )
    } else {
        let weight = float::div(
            float::sub(util_rate, high_kink),
            float::sub(float::from_quotient(1, 1), high_kink),
        );
        let range = float::sub(max_borrow_rate, borrow_rate_on_high_kink);

        float::add(
            float::mul(weight, range),
            borrow_rate_on_high_kink,
        )
    };

    borrow_rate
}

